use T15::{sum_formula, sum_range};

#[test]
fn bench_sum_range() {
    let iterations = 100_000u64;
    let mut total = 0u64;
    for _ in 0..iterations {
        total = total.wrapping_add(sum_range(1_000_000));
    }
    println!("sum_range benchmark total={}", total);
}

#[test]
